const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([-120.32, 39.31]); // Donner Pass, California
  const startDate = '2022-01-01';
  const endDate = '2022-04-30';
  const sweThresholdInches = 40.0;
  const sweThresholdMm = sweThresholdInches * 25.4; // Convert inches to millimeters

  // 2. Data Acquisition & Check
  const collectionId = 'NOHRSC/SNODAS';
  let collection = ee.ImageCollection(collectionId)
    .filterDate(startDate, endDate)
    .filterBounds(aoi)
    .select('swe');

  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log(`Evidence: No images found in ${collectionId} for the period.`);
    console.log(`A: No`);
    return;
  }
  console.log(`Image Count: ${collectionSize}`);

  // 3. Processing
  // Create an image that represents the maximum SWE value for each pixel over the time period.
  const maxSweImage = collection.max();

  // 4. Calculation
  // Extract the maximum SWE value at the point of interest.
  // SNODAS is ~1km resolution, so a larger scale is not necessary and might miss the peak value.
  const scale = 1000;
  const sweData = maxSweImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: aoi,
    scale: scale,
  }).get('swe');

  const maxSweMm = sweData.getInfo();

  // 5. Validation & Final Answer
  if (maxSweMm === null) {
    console.log('Evidence: Could not extract a valid pixel value at the location.');
    console.log('C3');
    return;
  }

  // A value of 0 is valid (no snow), so we only check for null.
  // A region reducer on a point should return only one pixel, so C2 is not applicable here.

  const maxSweInches = maxSweMm / 25.4;
  console.log(`Donner Pass Max SWE (Jan-Apr 2022): ${maxSweInches.toFixed(2)} inches`);
  console.log(`Threshold: > ${sweThresholdInches.toFixed(2)} inches`);

  if (maxSweInches > sweThresholdInches) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
